		aiState = new CAiSShotAt();
		break;
	case STATE_RELOAD:
		aiState = new CAiSReload(); /* 0x2dc718: 48 bytes */
		break;
	case STATE_NOAMMO:
		aiState = new CAiSNoAmmo();
		break;
	case STATE_PICKUP:
		aiState = new CAiSPickup(); /* 0x2dc6a0: 52 bytes */
		break;
	case STATE_HOSTAGE:
		aiState = new CAiSHostage();
		break;
	case STATE_CORPSE:
		aiState = new CAiSCorpse();
		break;
	case STATE_EVENT:
		aiState = new CAiSEvent();
		break;
	case STATE_TARGETING:
		aiState = new CAiSTarget();
