		m_critical = 0;
		m_first_tick = 1;
		m_aware = 255;
		m_seq = 255;
		m_mode = 1;
		m_anim = NULL;
		m_timer = 0.0f;
		m_keep_anim = 0;
		m_animset = NULL;
